"""Portable original sector formulas, generated by AST extraction; no API/SQL I/O."""
import json
import numpy as np
import pandas as pd
import pandas_market_calendars as mcal
SOURCE_PATH = 'src/sector_technical_features.py'
SOURCE_SHA256 = 'b3a91ef68a104f46db63305f77bfb087af61130174e8a90183ed2d50c963c82e'

PROXIES = {'Communication Services': 'VOX', 'Consumer Discretionary': 'XLY', 'Consumer Staples': 'XLP', 'Energy': 'XLE', 'Financials': 'XLF', 'Health Care': 'XLV', 'Industrials': 'XLI', 'Information Technology': 'XLK', 'Materials': 'XLB', 'Real Estate': 'XLRE', 'Utilities': 'XLU'}
CONTEXT_FEATURES = [*[f'sector_return_{n}d' for n in [21, 63, 126, 252]], 'sector_momentum_12_1', *[f'sector_realized_vol_{n}d' for n in [21, 63]], 'sector_price_to_sma50', 'sector_price_to_sma200', 'sector_drawdown_252d', *[f'sector_excess_market_return_{n}d' for n in [21, 63, 126]], 'sector_strength_rank_63d']
RELATIVE_FEATURES = ['stock_excess_sector_return_21d', 'stock_excess_sector_return_63d', 'stock_to_sector_vol_ratio_63d']
SECTOR_FEATURES = CONTEXT_FEATURES + RELATIVE_FEATURES

def calculate(prices):
    px = prices.copy()
    px['date'] = pd.to_datetime(px.date).astype('datetime64[ns]')
    if px.duplicated(['date', 'proxy_ticker']).any():
        raise ValueError('Duplicate sector ETF prices')
    calendar = mcal.get_calendar('NYSE').valid_days(px.date.min(), px.date.max()).tz_localize(None)
    expected = set(PROXIES.values()) | {'SPY'}
    if set(px.proxy_ticker) != expected:
        raise ValueError('Missing/unknown ETF proxies')
    parts = []
    for ticker, g in px.groupby('proxy_ticker'):
        g = g.set_index('date').reindex(calendar).rename_axis('date')
        p = g.adj_close
        r = p.pct_change(fill_method=None)
        z = pd.DataFrame({'date': calendar, 'proxy_ticker': ticker, 'proxy_source_date': calendar})
        for n in [21, 63, 126, 252]:
            z[f'sector_return_{n}d'] = (p / p.shift(n) - 1).to_numpy()
        z['sector_momentum_12_1'] = (p.shift(21) / p.shift(252) - 1).to_numpy()
        for n in [21, 63]:
            z[f'sector_realized_vol_{n}d'] = (r.rolling(n, min_periods=n).std(ddof=1) * np.sqrt(252)).to_numpy()
        for n in [50, 200]:
            z[f'sector_price_to_sma{n}'] = (p / p.rolling(n, min_periods=n).mean() - 1).to_numpy()
        z['sector_drawdown_252d'] = (p / p.rolling(252, min_periods=252).max() - 1).to_numpy()
        z.loc[g.adj_close.isna().to_numpy(), 'proxy_source_date'] = pd.NaT
        parts.append(z)
    all_features = pd.concat(parts, ignore_index=True)
    market = all_features.loc[all_features.proxy_ticker.eq('SPY'), ['date'] + [f'sector_return_{n}d' for n in [21, 63, 126]]].rename(columns={f'sector_return_{n}d': f'market_return_{n}d' for n in [21, 63, 126]})
    out = all_features.loc[~all_features.proxy_ticker.eq('SPY')].merge(market, on='date', validate='many_to_one')
    out['sector'] = out.proxy_ticker.map({v: k for k, v in PROXIES.items()})
    for n in [21, 63, 126]:
        out[f'sector_excess_market_return_{n}d'] = out[f'sector_return_{n}d'] - out[f'market_return_{n}d']
    out['sector_strength_rank_63d'] = out.groupby('date').sector_return_63d.rank(method='average', pct=True)
    out = out[['date', 'sector', 'proxy_ticker', 'proxy_source_date'] + CONTEXT_FEATURES].sort_values(['date', 'sector']).reset_index(drop=True)
    assert not out.duplicated(['date', 'sector']).any()
    assert out.sector.nunique() == 11
    return out

def join_frame(frame, membership, daily):
    x = frame.copy()
    x['signal_date'] = pd.to_datetime(x.signal_date).astype('datetime64[ns]')
    members = membership.rename(columns={'date': 'signal_date', 'latest_ticker': 'ticker'})[['signal_date', 'ticker', 'sector']].copy()
    members['signal_date'] = pd.to_datetime(members.signal_date).astype('datetime64[ns]')
    if members.duplicated(['signal_date', 'ticker']).any():
        raise ValueError('Ambiguous sector assignment')
    x = x.merge(members, on=['signal_date', 'ticker'], how='left', validate='one_to_one')
    if x.sector.isna().any():
        raise ValueError('Unmapped model sector')
    right = daily.rename(columns={'date': 'sector_technical_date'}).copy()
    right['sector_technical_date'] = pd.to_datetime(right.sector_technical_date).astype('datetime64[ns]')
    x = x.merge(right, left_on=['signal_date', 'sector'], right_on=['sector_technical_date', 'sector'], how='left', validate='many_to_one')
    for n in [21, 63]:
        x[f'stock_excess_sector_return_{n}d'] = x[f'return_{n}d'] - x[f'sector_return_{n}d']
    x['stock_to_sector_vol_ratio_63d'] = x.realized_vol_63d / x.sector_realized_vol_63d.replace(0, np.nan)
    if len(x) != len(frame) or not np.isfinite(x[SECTOR_FEATURES].to_numpy()).all():
        raise ValueError('Sector join changes sample or has incomplete predictors')
    assert x.sector_technical_date.eq(x.signal_date).all() and x.proxy_source_date.eq(x.signal_date).all()
    return x.sort_values(['signal_date', 'ticker']).reset_index(drop=True)


def from_observations(frame, *, run_id, row_cap=10000):
    """Select an explicit observation run; never silently select vendor latest."""
    frame = frame.loc[frame.run_id.eq(run_id)].copy()
    if frame.empty:
        raise ValueError('No observations for explicit run')
    frame = frame.loc[frame.entity.eq('prices') & frame.security_id.isna()]
    output=[]
    for _, row in frame.iterrows():
        values = json.loads(row['values']) if isinstance(row['values'],str) else row['values']
        output.append(dict(date=row.observation_date,proxy_ticker=row.api_lookup_ticker,
            adj_close=values.get('adjclose'),volume=values.get('volume')))
    prices=pd.DataFrame(output)
    if prices.empty or (prices.groupby('proxy_ticker').size()>row_cap).any():
        raise ValueError('Empty sector data or per-proxy compute cap exceeded')
    prices=prices.drop_duplicates()
    if prices.duplicated(['date','proxy_ticker']).any():
        raise ValueError('Conflicting observations within selected run')
    for c in ['adj_close','volume']:
        prices[c]=pd.to_numeric(prices[c],errors='raise')
        if prices[c].isna().any() or not np.isfinite(prices[c]).all():
            raise ValueError('Missing/nonfinite sector source value')
    if prices.adj_close.le(0).any() or prices.volume.lt(0).any():
        raise ValueError('Invalid sector adjusted price/volume')
    return calculate(prices)
